mapper.update:
	/**
    *       updateIcbtgAltmnt : isry.couns.mngr.icbtgmng.mapper.updateIcbtgAltmnt : 인큐베이팅 상담자배정표 상세 수정 
    */
        UPDATE
                AYC150  T1      /* 근무배정표_인큐베이팅 */
        SET
                T1.INCUBA_WORK_YMD      =       #{INCUBA_WORK_YMD}
                , T1.NTABRD_EVL_YN      =       #{NTABRD_EVL_YN}
                , T1.CHTT_EVL_YN        =       #{CHTT_EVL_YN}
                , T1.LAST_MDFR_ID       =       #{USER_ID}
                , T1.LAST_MDFCN_DT      =       SYSDATE
        WHERE   1=1
        AND     T1.INDEX_SN             =       #{INDEX_SN}

mapper.delete:
	/**
    *       deleteIcbtgAltmnt : isry.couns.mngr.icbtgmng.mapper.deleteIcbtgAltmnt : 인큐베이팅 상담자배정표 상세 삭제 
    */
        DELETE
        FROM    AYC150  T1      /* 근무배정표_인큐베이팅 */
        WHERE   1=1
        AND     T1.CONSTT_ID          =         #{CONSTT_ID}
        AND     T1.INCUBA_WORK_YMD    =         #{INCUBA_WORK_YMD}
